const keywords = ['Al Aqsa Mosque', 'Dome of the Rock', 'Jerusalem Old City', 'Masjid al-Aqsa aerial'];

async function searchPexels(query) {
  try {
    const response = await this.helpers.httpRequest({
      method: 'GET',
      url: `https://api.pexels.com/videos/search?query=${encodeURIComponent(query)}&per_page=1`,
      headers: {
        'Authorization': 'MUWFPcCJkFX0SqfSLSjYtZDx8fKmcY7hxtlUzhF4bR8tZRBrfCHQmkUo'
      },
      json: true
    });
    return response.videos && response.videos[0] ? response.videos[0] : null;
  } catch (e) {console.log('PEXELS ERROR:', e.message);
   return { error: e.message };
  }
}

const results = [];
for (const keyword of keywords) {
  const video = await searchPexels(keyword);
  results.push({ keyword, video });
}

return [{ json: { results } }];

