const fs = require('fs');
const { execSync } = require('child_process');

const basePath = 'C:\\Users\\Dell 5480\\';
const execOptions = { maxBuffer: 1024 * 1024 * 50 }; // 50MB buffer

for (let i = 0; i < 4; i++) {
  const inputFile = `${basePath}clip_${i}.mp4`;
  const standardized = `${basePath}std_clip_${i}.mp4`;
  const scaleCommand = `ffmpeg -y -loglevel error -i "${inputFile}" -vf "scale=1080:1920:force_original_aspect_ratio=decrease,pad=1080:1920:(ow-iw)/2:(oh-ih)/2,setsar=1,fps=30" -c:v libx264 -an "${standardized}"`;
