const filterCommand = `ffmpeg -y -loglevel error -i "${basePath}std_clip_0.mp4" -i "${basePath}std_clip_1.mp4" -i "${basePath}std_clip_2.mp4" -i "${basePath}std_clip_3.mp4" -filter_complex "[0:v][1:v][2:v][3:v]concat=n=4:v=1:a=0[outv]" -map "[outv]" -c:v libx264 "${basePath}combined_video.mp4"`;
